---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Agent inbox: Every run that needs you, is running or is done, in one list.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change agent-inbox.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './agent-inbox.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="agent-inbox" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="aib panel">
  <div class="aib-h"><b>Inbox</b></div>
  <div class="aib-gs"></div>
</div>
  </Fragment></div>
</div>
<script>
  import './agent-inbox.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Agent inbox ---------- */
/* every run in one list, grouped by what it needs: Needs you, Running, Done. A run glides to its new group when it moves.
   The card sits on two columns (owner, 18 Nov), its content 16px from every edge: the head's neutral mark in a 28px column
   with the agents' marks under it, and the title and each run's words 12px after it; the buttons and the clocks end on the
   content's right edge, and each row shares one centre line. Each group's name and count is a section label on the
   content's left edge, over the marks, so it never reads as another run's words. A run's row is not a button, so it has no
   hover fill, and one that failed keeps its red words and Retry with no red band behind them; a run that moves glides
   without lifting */
.aib{width:100%;max-width:440px;margin:0 auto;padding:16px 16px 6px}
.aib-h{display:flex;align-items:center;gap:12px;padding:0 0 4px}
.aib-hi{width:28px;height:28px;display:grid;place-items:center;flex:none;border-radius:var(--dm-r-sm);color:var(--dm-fg2);background:var(--dm-chip)}
.aib-h b{flex:1;min-width:0;font-weight:500;font-size:14px;line-height:20px}
.aib-g{display:flex;flex-direction:column}
.aib-gh{display:flex;align-items:center;gap:var(--dm-s-2);padding:12px 0 4px;font-size:12px;line-height:18px;color:var(--dm-muted)}
.aib-gh .n{font-variant-numeric:tabular-nums}
.aib-gl{display:flex;flex-direction:column}
.aib-i{display:flex;align-items:center;gap:12px;padding:8px 0;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;transition:background .16s}
.aib-i.mv{position:relative;z-index:1;background:var(--dm-surface)}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.aib :is(.ib,.pill):active,:root[data-style="clean"] .aib .ib:active,:root [data-style="clean"] .aib .ib:active,:root [data-style="clean"].aib .ib:active{transform:none}
.aib-av{width:28px;height:28px;border-radius:var(--dm-r-sm);display:grid;place-items:center;flex:none;font-size:11px;font-weight:500}
.aib-t{flex:1;min-width:0;display:flex;flex-direction:column}
.aib-t b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aib-t span{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aib-i.fail .aib-t span{color:var(--dm-bad)}
.aib-r{display:flex;align-items:center;gap:6px;flex:none;font-size:12.5px;color:var(--dm-fg2)}
.aib-r .spin{width:11px;height:11px;color:var(--dm-accent-fg,var(--dm-accent))}
.aib-r .ok{color:var(--dm-ok);display:grid}
.aib-i.fail .aib-r .pill{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.aib-i.fail .aib-r .pill:hover{box-shadow:var(--dm-on-tint-btn-h)}}
/* Clean (owner, 18 Nov): the head's mark has a hairline like the other tiles; the done ticks are the vivid mark green,
   never the darker text green; Retry is the secondary button as Clean draws it everywhere (its tokens) */
:root[data-style="clean"] .aib-hi,:root [data-style="clean"] .aib-hi,:root [data-style="clean"].aib-hi{box-shadow:inset 0 0 0 1px var(--dm-hair)}
/* a group's name is the list's section label (owner, 18 Nov), in the smaller muted label type of a menu's group heading, so
   it never reads as a run's description; a little more room above it sets the groups apart */
:root[data-style="clean"] .aib-gh,:root [data-style="clean"] .aib-gh,:root [data-style="clean"].aib-gh{padding-top:16px;font-size:11.5px;line-height:16px}
:root[data-style="clean"] .aib-r .ok,:root [data-style="clean"] .aib-r .ok,:root [data-style="clean"].aib-r .ok{color:var(--dm-ok-mark)}
:root[data-style="clean"] .aib-i.fail .aib-r .pill,:root [data-style="clean"] .aib-i.fail .aib-r .pill,:root [data-style="clean"].aib-i.fail .aib-r .pill{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .aib-i.fail .aib-r .pill:hover,:root [data-style="clean"] .aib-i.fail .aib-r .pill:hover,:root [data-style="clean"].aib-i.fail .aib-r .pill:hover{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .aib-i.fail .aib-r .pill:hover,:root [data-style="clean"] .aib-i.fail .aib-r .pill:hover,:root [data-style="clean"].aib-i.fail .aib-r .pill:hover{box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .aib-i.fail .aib-r .pill:active,:root [data-style="clean"] .aib-i.fail .aib-r .pill:active,:root [data-style="clean"].aib-i.fail .aib-r .pill:active{box-shadow:var(--dm-btn2-press)}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, enter, grow, html, swap, tip } from '../core/core.js';
DM.def('agent-inbox', (r, c) => {
  // the runs, grouped by what they need: one waits for approval, one failed and can be retried, two are running with their
  // clocks, two are done
  const A = { 'Design agent':['D','var(--dm-av-l)'], 'Build agent':['B','var(--dm-av-m)'], 'Research agent':['R','var(--dm-av-t)'], 'Copy agent':['C','var(--dm-av-p)'], 'QA agent':['Q','var(--dm-av-b)'] };
  const R = [
    { id:'pub', t:'Publish the pricing page', a:'Design agent', g:'needs', why:'Waiting for your approval' },
    { id:'tok', t:'Export tokens to CSS', a:'Build agent', g:'needs', fail:true, why:'Failed: rate limited by Figma', tip:'Figma answered 429 at 10:42. Safe to retry' },
    { id:'cards', t:'Rework the plan cards', a:'Design agent', g:'run', sec:102, doing:'Editing frame 3 of 6' },
    { id:'cmp', t:'Compare 3 competitor pages', a:'Research agent', g:'run', sec:38, doing:'Reading page 3 of 3' },
    { id:'copy', t:'Rewrite plan descriptions', a:'Copy agent', g:'done', ago:'12m ago' },
    { id:'aud', t:'Audit pricing contrast', a:'QA agent', g:'done', ago:'25m ago' }
  ];
  const GR = [['needs', 'Needs you'], ['run', 'Running'], ['done', 'Done']];
  const gs = $('.aib-gs', r);
  // the panel fits its rows at every moment (owner, 18 Nov: no room kept for a group that has gone): as a group goes or
  // comes back, its height eases with grow(), and it stays centred in its stage
  const ib = r.classList.contains('aib') ? r : $('.aib', r);
  // the head has a neutral mark in a tile, the column the agents' marks sit in (owner, 18 Nov)
  if (ib) $('.aib-h', ib).prepend(html(`<span class="aib-hi" aria-hidden="true">${I('mail')}</span>`));
  if (ib) c.offs.push(grow(ib));
  gs.innerHTML = GR.map(([k, n]) => `<section class="aib-g" data-g="${k}" aria-label="${n}"><div class="aib-gh"><span>${n}</span><span class="n"></span></div><div class="aib-gl" role="list"></div></section>`).join('');
  const clock = s => Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0');
  const meta = x => x.g === 'needs' ? x.why : x.g === 'run' ? x.doing : x.a;
  const right = x => x.g === 'needs' ? (x.fail ? `<button class="pill sm aib-go" aria-label="Retry ${x.t}">${I('refresh','xs')}Retry</button>` : `<button class="pill primary sm aib-go" aria-label="Approve ${x.t}">Approve</button>`)
    : x.g === 'run' ? `<span class="spin"></span><span class="num aib-ck">${clock(x.sec)}</span>` : `<span class="ok">${I('ok','xs')}</span><span>${x.ago}</span>`;
  function row(x){
    const [m, col] = A[x.a];
    x.el = html(`<div class="aib-i" role="listitem"><span class="aib-av" style="background:${col};color:${col.replace(')', '-ink)')}" aria-hidden="true">${m}</span><span class="aib-t"><b>${x.t}</b><span></span></span><span class="aib-r"></span></div>`);
    update(x, true); return x.el;
  }
  function update(x, now){
    const el = x.el, sp = $('.aib-t span', el), rr = $('.aib-r', el);
    el.classList.toggle('fail', !!x.fail && x.g === 'needs');
    if (x.tip && x.g === 'needs') sp.dataset.tip = x.tip; else delete sp.dataset.tip;
    if (now){ sp.textContent = meta(x); rr.innerHTML = right(x); } else { swap(sp, meta(x)); rr.innerHTML = right(x); enter(rr); }
    const b = $('.aib-go', el); if (b) b.onclick = () => act(x);
  }
  const list = g => $(`.aib-g[data-g="${g}"] .aib-gl`, gs);
  R.forEach(x => list(x.g).appendChild(row(x)));
  function counts(){
    // each group shows its count, and a group with nothing in it goes away
    GR.forEach(([k]) => { const n = R.filter(x => x.g === k).length, sec = $(`.aib-g[data-g="${k}"]`, gs); $('.n', sec).textContent = n; sec.hidden = !n; });
  }
  counts();
  // a run that moves glides to its place in the new group: rows and group titles are measured before and after, and eased
  // from where they were; the moving row rides above the rest, and a group that comes back fades in
  const ease = getComputedStyle(r).getPropertyValue('--dm-ease').trim() || 'ease';
  const shown = () => $$('.aib-g:not([hidden]) .aib-gh,.aib-g:not([hidden]) .aib-i', gs);
  function move(x, g){
    const first = new Map(shown().map(e => [e, e.getBoundingClientRect().top]));
    x.g = g; update(x); list(g).prepend(x.el); counts();
    if (REDUCE) return;
    x.el.classList.add('mv'); c.later(440, () => x.el.classList.remove('mv'));
    shown().forEach(e => { if (!first.has(e)) return enter(e); const d = first.get(e) - e.getBoundingClientRect().top; if (Math.abs(d) > 1) e.animate([{ transform:`translateY(${d}px)` }, { transform:'none' }], { duration:420, easing:ease }); });
  }
  // every running run's clock ticks
  c.every(1000, () => R.forEach(x => { if (x.g === 'run'){ x.sec++; const ck = $('.aib-ck', x.el); if (ck) ck.textContent = clock(x.sec); } }));
  // Approve starts the run and Retry tries a failed one again; either runs, then lands in Done
  function act(x){
    const retry = !!x.fail; x.fail = false; x.sec = 0; x.doing = retry ? 'Retrying the export' : 'Publishing to designme.studio/pricing';
    move(x, 'run');
    c.later(retry ? 5000 : 4000, () => { x.ago = 'Just now'; move(x, 'done'); });
  }
  // the research run finishes on its own while you look
  c.later(6000, () => { const x = R.find(y => y.id === 'cmp'); if (x.g === 'run'){ x.ago = 'Just now'; move(x, 'done'); } });
  // the preview's story: read why the export failed, approve the publish, and retry the export
  c.story(async s => {
    const by = id => R.find(x => x.id === id);
    await s.beat(3);
    await s.point($('.aib-t span', by('tok').el)); await s.beat(3);
    await s.tap($('.aib-go', by('pub').el)); s.away(); await s.beat(5);
    await s.tap($('.aib-go', by('tok').el)); s.away();
    await s.until(() => by('tok').g === 'done' && by('pub').g === 'done'); await s.beat(3);
  });
});
